CREATE TABLE t1(a TEXT, b INT, c INT, d INT); CREATE INDEX t1abc ON t1(a,b,c); INSERT INTO t1 VALUES('abc',123,4,5); INSERT INTO t1 VALUES('abc',234,5,6); INSERT INTO t1 VALUES('abc',234,6,7); INSERT INTO t1 VALUES('abc',345,7,8); INSERT INTO t1 VALUES('def',567,8,9); INSERT INTO t1 VALUES('def',345,9,10); INSERT INTO t1 VALUES('bcd',100,6,11); ANALYZE; DELETE FROM sqlite_stat1; INSERT INTO sqlite_stat1 VALUES('t1','t1abc','10000 5000 2000 10'); INSERT INTO sqlite_stat1 VALUES('t1j',NULL,'3'); ANALYZE sqlite_master; CREATE TABLE t1j(x TEXT, y INTEGER); INSERT INTO t1j VALUES('one',1),('six',6),('ninty-nine',99);